create or replace function app_private.can_answer_idea_question(p_idea_id uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.ideas i where i.id=p_idea_id and (app_private.can_write_idea(i.id) or (app_private.can_access_idea(i.id) and i.status in ('draft','exploring','ready_for_review','in_review','needs_work','parked')))) $$;
create or replace function public.answer_idea_question_v3(p_idea_id uuid,p_question_item_id uuid,p_answer text) returns jsonb language plpgsql security definer set search_path='' as $$ declare v_user uuid:=auth.uid(); v_id uuid; begin if v_user is null or not app_private.can_answer_idea_question(p_idea_id) then raise exception 'FORBIDDEN'; end if; if not exists(select 1 from public.idea_items where id=p_question_item_id and idea_id=p_idea_id and kind='question') then raise exception 'QUESTION_NOT_FOUND'; end if; if nullif(btrim(p_answer),'') is null then raise exception 'ANSWER_REQUIRED'; end if; insert into public.idea_question_answers(idea_id,question_item_id,answered_by,answer) values(p_idea_id,p_question_item_id,v_user,btrim(p_answer)) on conflict(question_item_id,answered_by) do update set answer=excluded.answer,updated_at=now() returning id into v_id; update public.idea_items set state='resolved' where id=p_question_item_id and idea_id=p_idea_id; update public.ideas set version=version+1,updated_at=now(),status=case when status='approved' then 'needs_work' else status end,readiness=case when status='approved' then 'decision' else readiness end where id=p_idea_id; return jsonb_build_object('answer_id',v_id,'question_item_id',p_question_item_id,'state','resolved'); end $$;
create or replace function public.answer_new_idea_question_v3(p_idea_id uuid,p_question text,p_why text,p_answer text) returns jsonb language plpgsql security definer set search_path='' as $$ declare v_user uuid:=auth.uid(); v_item uuid; v_answer uuid; begin if v_user is null or not app_private.can_answer_idea_question(p_idea_id) then raise exception 'FORBIDDEN'; end if; if nullif(btrim(p_question),'') is null or nullif(btrim(p_answer),'') is null then raise exception 'QUESTION_AND_ANSWER_REQUIRED'; end if; insert into public.idea_items(idea_id,kind,title,body,state,created_by) values(p_idea_id,'question',btrim(p_question),coalesce(p_why,''),'resolved',v_user) returning id into v_item; insert into public.idea_question_answers(idea_id,question_item_id,answered_by,answer) values(p_idea_id,v_item,v_user,btrim(p_answer)) returning id into v_answer; update public.ideas set version=version+1,updated_at=now(),status=case when status='approved' then 'needs_work' else status end,readiness=case when status='approved' then 'decision' else readiness end where id=p_idea_id; return jsonb_build_object('question_item_id',v_item,'answer_id',v_answer,'state','resolved'); end $$;
